Dataspatium.assets.register("webr/vfs/etc/fonts/fonts.conf","text","<?xml version=\"1.0\"?>\n<!DOCTYPE fontconfig SYSTEM \"fonts.dtd\">\n<fontconfig>\n    <dir>/usr/share/fonts</dir>\n    <dir>/home/web_user/fonts</dir>\n    <cachedir>/var/cache/fontconfig</cachedir>\n\n    <alias>\n        <family>Helvetica</family>\n        <prefer><family>sans-serif</family></prefer>\n    </alias>\n    <alias>\n        <family>Times</family>\n        <prefer><family>serif</family></prefer>\n    </alias>\n    <alias>\n        <family>Courier</family>\n        <prefer><family>monospace</family></prefer>\n    </alias>\n\n    <alias>\n        <family>sans</family>\n        <prefer><family>sans-serif</family></prefer>\n    </alias>\n    <alias>\n        <family>mono</family>\n        <prefer><family>monospace</family></prefer>\n    </alias>\n\n    <alias>\n        <family>sans-serif</family>\n        <prefer><family>Noto Sans</family></prefer>\n    </alias>\n    <alias>\n        <family>serif</family>\n        <prefer><family>Noto Serif</family></prefer>\n    </alias>\n    <alias>\n        <family>monospace</family>\n        <prefer><family>Noto Sans Mono</family></prefer>\n    </alias>\n</fontconfig>\n");
